  from jsonb_array_elements($J$[["faq.a18",15,"Enter your email address and we'll send you a sign-in link and code. You don't need a password.",null,null,false,309],["faq.q19",15,"How do I delete my account?",null,null,false,310],["faq.a19",15,"Go to My account → Profile → Delete account. Your personal details are removed; we keep order records only as long as the law requires.",null,null,false,311],["faq.q20",15,"How do I unsubscribe from the newsletter?",null,null,false,312],["faq.a20",15,"Click “Unsubscribe” at the bottom of any newsletter, or change your preferences in your account.",null,null,false,313],["shipping.title",16,"Shipping & delivery",null,null,false,314],["shipping.intro",16,"Every printed book is printed on demand for your order by our print partner and shipped worldwide.",null,null,false,315],["shipping.how.title",16,"How it works",null,null,false,316],["shipping.how.text",16,"After you order, we send your book to print. It is printed, bound and dispatched, usually within {production_days} working days.","{production_days} is filled in from Settings and follows our print partner's current production times. Keep {placeholders} exactly as written",null,false,317],["shipping.options.title",16,"Shipping options",null,null,false,318],["shipping.options.text",16,"At checkout you choose a shipping option. Each option shows its price and estimated delivery time for your address before you pay.",null,null,false,319],["shipping.option.estimate",16,"Estimated delivery {min}–{max} working days after dispatch","Shown next to each shipping option at checkout",null,false,320],["shipping.option.untracked",16,"Untracked · cheaper, no tracking number · can take about 4 weeks to Europe","Shown below the tracked options at checkout. New in v1.3",null,false,321],["shipping.estimates_note",16,"Production and delivery times are estimates from our print partner and carriers, not guarantees. They can be longer in busy periods such as December.",null,null,false,322],["shipping.free",16,"Free shipping on orders over {amount}.",null,null,false,323],["shipping.tracking.title",16,"Tracking",null,null,false,324],["shipping.tracking.text",16,"Tracked shipping options come with a tracking number, emailed as soon as your order is dispatched. Untracked shipping is cheaper but has no tracking number and can take longer.",null,null,false,325],["shipping.customs.title",16,"Customs and import taxes",null,null,false,326],["shipping.customs.text",16,"Most books are printed in the United Kingdom; orders to the United States, Canada and Australia are usually printed locally. For deliveries from the United Kingdom to the European Union and other countries, import VAT or duties may apply. These are set by your local authorities and paid by the recipient.","CONFIRM — client to check the English before translating — may change if VAT is collected at checkout (IOSS)",null,true,327],["shipping.ebooks.title",16,"Ebooks",null,null,false,328],["shipping.ebooks.text",16,"Ebooks have no shipping costs and are available immediately after payment.",null,null,false,329],["shipping.holidays",16,"Around public holidays, printing and delivery may take a little longer.",null,null,false,330],["returns.title",17,"Returns",null,null,false,331],["returns.intro",17,"You can withdraw from your purchase of a printed book within 14 days of receiving it, without giving a reason.","CONFIRM — client to check the English before translating — draft based on EU consumer law and our print partner's policy; legal check pending",null,true,332],["returns.how.title",17,"How to return a book",null,null,false,333],["returns.step1",17,"Let us know within 14 days of receiving your order: email info@obeliskbooks.com with your order number and the book(s) you want to return, or use the model withdrawal form on our right of withdrawal page.","CONFIRM — client to check the English before translating — draft based on EU consumer law and our print partner's policy; legal check pending",null,true,334],["returns.step2",17,"Send the book(s) back within 14 days after letting us know, to: Obelisk Media B.V., Returns, Zinkstraat 24, 4823 AD Breda, The Netherlands.","CONFIRM — client to check the English before translating. Do not translate the address",null,true,335],["returns.condition",17,"Please pack books well and return them undamaged. If a book has been handled more than needed to look at it, we may deduct the loss in value from your refund.","CONFIRM — client to check the English before translating — draft based on EU consumer law and our print partner's policy; legal check pending",null,true,336],["returns.costs",17,"You pay the cost of sending the book back. We recommend a tracked service.","CONFIRM — client to check the English before translating — draft based on EU consumer law and our print partner's policy; legal check pending",null,true,337],["returns.refund",17,"We refund the purchase price and the original standard shipping cost within 14 days of your request, to your original payment method. We may wait to refund until we have received the book back.","CONFIRM — client to check the English before translating — draft based on EU consumer law and our print partner's policy; legal check pending",null,true,338],["returns.damaged.title",17,"Damaged, misprinted or faulty books",null,null,false,339],["returns.damaged.text",17,"Every book is printed just for you, so if something is wrong, we will put it right. Email order@obeliskbooks.com within 14 days of delivery with your order number, the book(s) affected and photos of the problem (and of the packaging if it arrived damaged). We will send you a free reprint or refund you in full. You do not need to send the book back unless we ask.","CONFIRM — client to check the English before translating — draft based on EU consumer law and our print partner's policy; legal check pending",null,true,340],["returns.lost.title",17,"Order not arrived?",null,null,false,341],["returns.lost.text",17,"If your order has not arrived by the latest estimated delivery date, or tracking has not updated for 7 working days, email order@obeliskbooks.com and we will look into it with the carrier.","PENDING — wording follows the client’s decision on lost untracked parcels (start of Phase 4). CONFIRM — legal check pending",null,true,342],["returns.ebooks",17,"Ebooks can't be returned once they have been delivered. See our right of withdrawal page.",null,null,false,343],["payment.title",18,"Payment methods",null,null,false,344],["payment.intro",18,"All payments are processed securely by Stripe. We never see or store your card details.","Keep 'Stripe'",null,false,345],["payment.methods",18,"Credit and debit cards (Visa, Mastercard, American Express), PayPal, iDEAL, Bancontact, Apple Pay and Google Pay.","Keep brand names",null,false,346],["payment.currency",18,"Pay in euros or US dollars. In many countries you can also pay in your local currency at checkout.",null,null,false,347],["payment.vat",18,"All prices include VAT. VAT for your country is calculated at checkout.",null,null,false,348],["payment.receipt",18,"You'll receive a receipt by email after payment. Need an invoice with your company details? Email order@obeliskbooks.com.",null,null,false,349],["legal.privacy.title",19,"Privacy policy",null,null,false,350],["legal.terms.title",19,"Terms & conditions",null,null,false,351],["legal.withdrawal.title",19,"Right of withdrawal",null,null,false,352],["legal.last_updated",19,"Last updated: {date}",null,null,false,353],["cart.title",20,"Your cart",null,null,false,354],["cart.empty",20,"Your cart is empty.",null,null,false,355],["cart.empty_cta",20,"Browse books","Button",null,false,356],["cart.col.item",20,"Item","Column",null,false,357],["cart.col.price",20,"Price","Column",null,false,358],["cart.col.qty",20,"Quantity","Column",null,false,359],["cart.col.total",20,"Total","Column",null,false,360],["cart.subtotal",20,"Subtotal",null,null,false,361],["cart.discount",20,"Discount",null,null,false,3